def transform(grid):
    import copy
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [[0]*w for _ in range(h)]
    # background = most common color
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    # line color: the remaining color forming a full-height/width line (color 2-ish, single straight line)
    colors = {}
    for i in range(h):
        for j in range(w):
            v = grid[i][j]
            if v != bg:
                colors.setdefault(v, []).append((i, j))
    line_c = None
    for v, ps in colors.items():
        cols = {p[1] for p in ps}
        rows = {p[0] for p in ps}
        if len(cols) == 1 and len(rows) > len(cols):
            line_c = v
            line_col = cols.pop()
    shape_c = [v for v in colors if v != line_c][0]
    pts = colors[shape_c]
    # erase shape and any color-8 column from background copy
    for i in range(h):
        for j in range(w):
            out[i][j] = bg
    # line stays
    for i in range(h):
        out[i][line_col] = line_c
    # move shape so its left edge is at line_col+1
    minc = min(p[1] for p in pts)
    shift = (line_col + 1) - minc
    maxc = max(p[1] for p in pts)
    for (i, j) in pts:
        out[i][j + shift] = shape_c
    # full-height column of 8 right of moved shape
    for i in range(h):
        out[i][maxc + shift + 1] = 8
    return out
